const {request}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const base='http://127.0.0.1:4183', r=await request.newContext(), results=[];let token='',cid,pid;const mark=(name,data)=>{results.push({name,data});console.log(name,JSON.stringify(data))};const req=async(path,method='GET',data,auth=true)=>{const res=await r.fetch(base+path,{method,data,headers:auth&&token?{Authorization:'Bearer '+token}:{}});return{status:res.status(),data:await res.json().catch(()=>({}))}};
try{const login=await req('/api/admin/v1/auth/login','POST',{email:'admin@dracula-food.com',password:'Dracula121.'});token=login.data.access_token;mark('admin login',{status:login.status,role:login.data.user?.roles});
mark('anon admin',await req('/api/admin/v1/products','GET',undefined,false));
let cat=await req('/api/admin/v1/categories','POST',{name:{ro:'QA Audit Food Category',en:'QA Audit Food Category',de:'QA Audit Food Kategorie'},description:{ro:'QA audit temporar'},is_active:true});cid=cat.data.id;mark('category create',cat);if(!cid)throw Error('No category created');
let boot=await req('/api/dracula/bootstrap');mark('category visible',boot.data.categories.filter(x=>x.name.includes('QA')));
mark('category deactivate',await req('/api/admin/v1/categories/'+cid,'PATCH',{is_active:false}));boot=await req('/api/dracula/bootstrap');mark('inactive still public',boot.data.categories.filter(x=>x.name.includes('QA')));
mark('category activate',await req('/api/admin/v1/categories/'+cid,'PATCH',{is_active:true}));
let product=await req('/api/admin/v1/products','POST',{sku:'QA-FOOD-AUDIT-'+Date.now(),status:'draft',price_ron:1,stock_quantity:0,category_ids:[cid],translations:{ro:{name:'QA Audit Food Product',description:'QA draft'},en:{name:'QA Audit Food Product'},de:{name:'QA Audit Food Produkt'}}});pid=product.data.id;mark('product create',{status:product.status,id:pid,data:pid?undefined:product.data});if(!pid)throw Error('No product created');
mark('product update',await req('/api/admin/v1/products/'+pid,'PATCH',{price_ron:2,translations:{de:{name:'QA Audit Food Produkt Aktualisiert'}}}));
mark('translation create',await req('/api/admin/v1/translations','PUT',{entries:[{key:'qa.independent_food_audit',values:{ro:'QA test română',en:'QA English',de:'QA Deutsch'}}]}));boot=await req('/api/dracula/bootstrap?lang=de');mark('translation served',boot.data.ui['qa.independent_food_audit']);
mark('translation delete',await req('/api/admin/v1/translations/qa.independent_food_audit','DELETE'));
mark('product delete',await req('/api/admin/v1/products/'+pid,'DELETE'));pid=null;
mark('category delete',await req('/api/admin/v1/categories/'+cid,'DELETE'));cid=null;
const foreign=await r.post(base+'/api/account/login',{headers:{Origin:'https://foreign.invalid'},data:{email:'client@dracula-food.com',password:'unused'}});mark('foreign origin',{status:foreign.status(),data:await foreign.json()});
const customer=await request.newContext();const cust=await customer.post(base+'/api/account/login',{data:{email:'client@dracula-food.com',password:'Dracula121.'}});mark('customer api login',{status:cust.status()});const cs=await customer.get(base+'/api/admin/v1/products');mark('customer forbidden admin',{status:cs.status(),data:await cs.json()});const cross=await customer.get('http://127.0.0.1:4181/api/account/profile');mark('food cookie no design access',{status:cross.status(),data:await cross.json()});
const noCsrf=await customer.patch(base+'/api/account/profile',{data:{full_name:'MUST NOT APPLY QA'}});mark('missing csrf',{status:noCsrf.status(),data:await noCsrf.json()});await customer.dispose();
}catch(e){mark('failure',e.stack)}finally{if(pid)mark('cleanup product',await req('/api/admin/v1/products/'+pid,'DELETE'));if(cid)mark('cleanup category',await req('/api/admin/v1/categories/'+cid,'DELETE'));fs.writeFileSync('work/audit-food-api-results.json',JSON.stringify(results,null,2));await r.dispose()}})();
